import Value = require( './index' );


// TESTS //

// The function returns a value instance...
{
	new Value(); // $ExpectType Value
	new Value( {} ); // $ExpectType Value
	new Value( { 'field': 'price' } ); // $ExpectType Value
	new Value( { 'field': 'price', 'scale': 'xScale', 'round': true } ); // $ExpectType Value

	Value(); // $ExpectType Value
	Value( {} ); // $ExpectType Value
	Value( { 'field': 'price' } ); // $ExpectType Value
	Value( { 'field': 'price', 'scale': 'xScale', 'round': true } ); // $ExpectType Value
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Value( '5' ); // $ExpectError
	new Value( 5 ); // $ExpectError
	new Value( true ); // $ExpectError
	new Value( false ); // $ExpectError
	new Value( null ); // $ExpectError
	new Value( [] ); // $ExpectError
	new Value( ( x: number ): number => x ); // $ExpectError

	Value( '5' ); // $ExpectError
	Value( 5 ); // $ExpectError
	Value( true ); // $ExpectError
	Value( false ); // $ExpectError
	Value( null ); // $ExpectError
	Value( [] ); // $ExpectError
	Value( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a `band` option which is not a number...
{
	new Value( { 'band': '5' } ); // $ExpectError
	new Value( { 'band': true } ); // $ExpectError
	new Value( { 'band': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `color` option which is not an object...
{
	new Value( { 'color': '5' } ); // $ExpectError
	new Value( { 'color': 5 } ); // $ExpectError
	new Value( { 'color': true } ); // $ExpectError
}

// The compiler throws an error if the function is provided an `exponent` option which is not a number or a value instance...
{
	new Value( { 'exponent': '5' } ); // $ExpectError
	new Value( { 'exponent': true } ); // $ExpectError
	new Value( { 'exponent': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `field` option which is not a string or an object...
{
	new Value( { 'field': 5 } ); // $ExpectError
	new Value( { 'field': true } ); // $ExpectError
	new Value( { 'field': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `mult` option which is not a number or a value instance...
{
	new Value( { 'mult': '5' } ); // $ExpectError
	new Value( { 'mult': true } ); // $ExpectError
	new Value( { 'mult': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided an `offset` option which is not a number or a value instance...
{
	new Value( { 'offset': '5' } ); // $ExpectError
	new Value( { 'offset': true } ); // $ExpectError
	new Value( { 'offset': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `round` option which is not a boolean...
{
	new Value( { 'round': '5' } ); // $ExpectError
	new Value( { 'round': 5 } ); // $ExpectError
	new Value( { 'round': null } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `scale` option which is not a string or a field descriptor...
{
	new Value( { 'scale': 5 } ); // $ExpectError
	new Value( { 'scale': true } ); // $ExpectError
	new Value( { 'scale': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided a `signal` option which is not a string...
{
	new Value( { 'signal': 5 } ); // $ExpectError
	new Value( { 'signal': true } ); // $ExpectError
	new Value( { 'signal': false } ); // $ExpectError
}

// The compiler throws an error if the function is provided more than one argument...
{
	new Value( {}, {} ); // $ExpectError
	Value( {}, {} ); // $ExpectError
}

// A value instance has value properties...
{
	const v = new Value();

	const band = v.band; // $ExpectType number | undefined
	const color = v.color; // $ExpectType Record<string, unknown> | undefined
	const exponent = v.exponent; // $ExpectType number | Value | undefined
	const field = v.field; // $ExpectType string | Record<string, unknown> | undefined
	const mult = v.mult; // $ExpectType number | Value | undefined
	const offset = v.offset; // $ExpectType number | Value | undefined
	const round = v.round; // $ExpectType boolean | undefined
	const scale = v.scale; // $ExpectType string | Record<string, unknown> | undefined
	const signal = v.signal; // $ExpectType string | undefined
	const value = v.value; // $ExpectType any

	const list = [
		band,
		color,
		exponent,
		field,
		mult,
		offset,
		round,
		scale,
		signal,
		value
	];
	if ( list.length !== 10 ) {
		throw new Error( 'unexpected error' );
	}
}

// The compiler throws an error if a value property is assigned an unsupported value...
{
	const v = new Value();

	v.band = '5'; // $ExpectError
	v.color = 5; // $ExpectError
	v.field = true; // $ExpectError
	v.round = '5'; // $ExpectError
	v.scale = 5; // $ExpectError
	v.signal = 5; // $ExpectError
}

// A value instance has a read-only `properties` property...
{
	const v = new Value();

	const props = v.properties; // $ExpectType string[]
	if ( props.length !== 10 ) {
		throw new Error( 'unexpected error' );
	}
	v.properties = [ 'field' ]; // $ExpectError
}

// A value instance has a `toJSON` method which returns a JSON object...
{
	const v = new Value();

	v.toJSON(); // $ExpectType JSON
}

// The compiler throws an error if the `toJSON` method is provided arguments...
{
	const v = new Value();

	v.toJSON( {} ); // $ExpectError
}
